    "U156": {
      "id": "U156",
      "publisher": "Romanian Maritime Hydrographic Directorate",
      "title": "KHORYV navigation notices ARN153–156 and ARN158: capsized, partially submerged and afloat",
      "url": "https://www.dhmfn.ro/ro/informatii-de-interes-public/avize-radio-pentru-navigatori/",
      "dateLabel": "23–27 October 2026; checked 28 October",
      "audit": "Full current primary notice read 24 October. Cancels ARN149. Says capsized at10:06 local and remains afloat inverted; three missing. Coordinates identify capsize/navigation hazard, not necessarily strike. Takes precedence over press sinking wording. Rechecked 25 October: ARN154 cancels ARN153, with later navigation-hazard position at 11:03 local on 24 October; still afloat inverted. Earlier ARN153 coordinates retained as dated history, not the current position or a strike coordinate. ARN155 directly read 26 October, cancels ARN154. Partially submerged but still afloat inverted, dated 25 October 11:00 local position 43°55.25′N,028°57.40′E; three missing and one-nautical-mile safety distance. Does not supply strike coordinates. ARN156 directly read 27 October at approximately 11:34 UTC, cancelling ARN155. The 27 October 06:18 local observation places the still-afloat, inverted and partially submerged vessel at 43°51.24′N, 028°54.54′E; three missing and one-nautical-mile safety recommendation remain. The position is a dated navigation hazard, not the strike coordinate or evidence of a new territorial incursion. ARN158 directly read 28 October, cancelling ARN156. Published 27 October, it reports the inverted, partially submerged but still afloat vessel at 43°49.50′N, 028°53.37′E at 12:00 local on 27 October; three missing and the one-nautical-mile safety recommendation remain. ARN157 concerns an unrelated maritime exercise. No new strike or territorial entry is inferred."
    },
